import{_ as a,c as e,o as r,a6 as s}from"./chunks/framework.BY05barL.js";const u=JSON.parse('{"title":"Procesos y Programas","description":"","frontmatter":{},"headers":[],"relativePath":"repaso/procesos-programas.md","filePath":"repaso/procesos-programas.md"}'),n={name:"repaso/procesos-programas.md"};function i(t,o,c,d,l,m){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="procesos-y-programas" tabindex="-1">Procesos y Programas <a class="header-anchor" href="#procesos-y-programas" aria-label="Permalink to &quot;Procesos y Programas&quot;">​</a></h1><h2 id="diferencia-entre-programa-y-proceso" tabindex="-1">Diferencia entre programa y proceso <a class="header-anchor" href="#diferencia-entre-programa-y-proceso" aria-label="Permalink to &quot;Diferencia entre programa y proceso&quot;">​</a></h2><p>El <strong>programa</strong> es una entidad <strong>pasiva</strong>: un archivo con instrucciones. El <strong>proceso</strong> es una entidad <strong>activa</strong>: un programa en ejecución, con su estado, sus recursos y su contexto. Un mismo programa puede dar origen a varios procesos.</p><table tabindex="0"><thead><tr><th></th><th>Programa</th><th>Proceso</th></tr></thead><tbody><tr><td>Naturaleza</td><td>Pasiva (archivo con instrucciones)</td><td>Activa (programa en ejecución)</td></tr><tr><td>Dónde se almacena</td><td>Almacenamiento secundario (disco), como archivo ejecutable</td><td>Memoria principal (RAM); su información de control, en el PCB</td></tr><tr><td>Qué lo compone</td><td>Código, datos estáticos e inicializados, encabezado con metadatos</td><td>Imagen en memoria (código, datos, heap y pila) + PCB</td></tr></tbody></table><h2 id="¿donde-se-almacenan" tabindex="-1">¿Dónde se almacenan? <a class="header-anchor" href="#¿donde-se-almacenan" aria-label="Permalink to &quot;¿Dónde se almacenan?&quot;">​</a></h2><ul><li>El <strong>programa</strong> se guarda en almacenamiento secundario (disco), como archivo ejecutable.</li><li>El <strong>proceso</strong> reside en memoria principal (RAM), y el sistema operativo guarda su información de control en el <strong>PCB</strong> (<em>Process Control Block</em>), dentro de la <strong>tabla de procesos</strong> del kernel.</li></ul><h2 id="¿que-informacion-los-compone" tabindex="-1">¿Qué información los compone? <a class="header-anchor" href="#¿que-informacion-los-compone" aria-label="Permalink to &quot;¿Qué información los compone?&quot;">​</a></h2><p><strong>Programa:</strong></p><ul><li>Código (instrucciones)</li><li>Datos estáticos o inicializados</li><li>Encabezado con metadatos: número mágico, tamaños de las secciones, punto de entrada, tabla de símbolos e información de reubicación</li></ul><p><strong>Proceso:</strong> su imagen en memoria (código, datos, heap y pila) más el PCB, que contiene:</p><ul><li>PID</li><li>Estado</li><li>Contador de programa</li><li>Registros de CPU</li><li>Prioridad e información de planificación</li><li>Información de memoria (tablas de páginas)</li><li>Archivos abiertos y estado de E/S</li><li>Contabilidad de uso de recursos</li><li>Datos del proceso padre e hijos</li></ul><h2 id="¿como-le-pasa-datos-un-proceso-a-otro" tabindex="-1">¿Cómo le pasa datos un proceso a otro? <a class="header-anchor" href="#¿como-le-pasa-datos-un-proceso-a-otro" aria-label="Permalink to &quot;¿Cómo le pasa datos un proceso a otro?&quot;">​</a></h2><p>Mediante mecanismos de <strong>comunicación entre procesos (IPC)</strong>. Los dos modelos principales son:</p><ul><li><strong>Memoria compartida:</strong> ambos procesos acceden a una misma región de memoria y se sincronizan con semáforos o mutex.</li><li><strong>Paso de mensajes:</strong> con las primitivas <code>send</code> / <code>receive</code>.</li></ul><p>En la práctica se usan pipes, colas de mensajes, sockets, señales y archivos.</p><p>Ver <a href="./../unidad1/programas-procesos.html#diferencias-entre-programa-y-proceso">Programas y Procesos</a>.</p>',16)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
